<?php
class Reporte_descuentos_model extends CI_Model{
 public function usuario_tiene_rol($u,$r){return !empty($this->db->query("SELECT 1 x FROM usuario u INNER JOIN rol_usuario ru ON ru.tipousuario_id=u.tipousuario_id WHERE u.usuario_id=? AND ru.rol_id=? AND ru.rolusuario_asignado=1 LIMIT 1",array((int)$u,(int)$r))->row_array());}
 public function listas(){return array('usuarios'=>$this->db->query("SELECT usuario_id,usuario_nombre,usuario_login FROM usuario ORDER BY usuario_nombre")->result_array(),'rutas'=>$this->db->query("SELECT ruta_id,ruta_nombre FROM ruta ORDER BY ruta_nombre")->result_array(),'tipos'=>$this->db->query("SELECT tipodescuento_id,tipodescuento_nombre FROM tipo_descuento_pasaje WHERE estado_id=1 ORDER BY tipodescuento_nombre")->result_array());}
 private function where($f,&$p){$w="DATE(d.descuento_fechahora) BETWEEN ? AND ? AND d.estado_id=1";$p=array($f['desde'],$f['hasta']);if($f['usuario_id']>0){$w.=" AND d.usuario_id=?";$p[]=$f['usuario_id'];}if($f['ruta_id']>0){$w.=" AND v.ruta_id=?";$p[]=$f['ruta_id'];}if($f['tipodescuento_id']>0){$w.=" AND d.tipodescuento_id=?";$p[]=$f['tipodescuento_id'];}return $w;}
 public function resumen($f){$p=array();$w=$this->where($f,$p);$sql="SELECT d.usuario_id,COALESCE(NULLIF(u.usuario_nombre,''),u.usuario_login,CONCAT('ID ',d.usuario_id)) usuario,COUNT(*) cantidad,SUM(d.descuento_importe) importe,SUM(d.descuento_preciooriginal) precio_original,SUM(d.descuento_preciofinal) precio_final,CASE WHEN SUM(d.descuento_preciooriginal)>0 THEN SUM(d.descuento_importe)*100/SUM(d.descuento_preciooriginal) ELSE 0 END porcentaje FROM venta_pasaje_descuento d LEFT JOIN usuario u ON u.usuario_id=d.usuario_id LEFT JOIN viaje v ON v.viaje_id=d.viaje_id WHERE $w GROUP BY d.usuario_id,u.usuario_nombre,u.usuario_login ORDER BY importe DESC,cantidad DESC";return $this->db->query($sql,$p)->result_array();}
 public function detalle($f){$p=array();$w=$this->where($f,$p);$sql="SELECT d.ventadescuento_id,d.venta_id,d.descuento_fechahora fecha,COALESCE(NULLIF(u.usuario_nombre,''),u.usuario_login,CONCAT('ID ',d.usuario_id)) usuario,COALESCE(NULLIF(ua.usuario_nombre,''),ua.usuario_login,'') autoriza,COALESCE(td.tipodescuento_nombre,CONCAT('Tipo ',d.tipodescuento_id)) tipo,COALESCE(r.ruta_nombre,CONCAT_WS(' - ',r.inicio_ruta,r.fin_ruta)) ruta,d.descuento_preciooriginal precio_original,d.descuento_importe descuento,d.descuento_preciofinal precio_final,CASE WHEN d.descuento_preciooriginal>0 THEN d.descuento_importe*100/d.descuento_preciooriginal ELSE 0 END porcentaje,d.descuento_motivo motivo FROM venta_pasaje_descuento d LEFT JOIN usuario u ON u.usuario_id=d.usuario_id LEFT JOIN usuario ua ON ua.usuario_id=d.usuario_autoriza_id LEFT JOIN tipo_descuento_pasaje td ON td.tipodescuento_id=d.tipodescuento_id LEFT JOIN viaje v ON v.viaje_id=d.viaje_id LEFT JOIN ruta r ON r.ruta_id=v.ruta_id WHERE $w ORDER BY d.descuento_fechahora DESC,d.ventadescuento_id DESC";return $this->db->query($sql,$p)->result_array();}
}
